//
//  ScriptTextTable.swift
//  RagnarokLocalization
//
//  Translates rAthena NPC script text (dialog messages and menu items)
//  with ScriptText.json generated by ragnarok-script-translator.
//

import Foundation

final public class ScriptTextTable: @unchecked Sendable {
    public static let shared = ScriptTextTable()

    private struct Template {
        var prefix: String
        var regex: NSRegularExpression
        var placeholderIndices: [Int]
        var translation: String
    }

    private let textsByKey: [String : String]
    private let templates: [Template]

    private var cache: [String : String] = [:]
    private let lock = NSLock()

    /// Loads the table in the background so the first NPC dialog does not stall.
    public static func preload() {
        Task.detached(priority: .utility) {
            _ = ScriptTextTable.shared
        }
    }

    public init(localization: String = "zh-Hant") {
        let url = Bundle.module.url(forResource: "ScriptText", withExtension: "json", subdirectory: nil, localization: localization)
            ?? Bundle.module.url(forResource: "ScriptText", withExtension: "json")

        guard let url,
              let data = try? Data(contentsOf: url),
              let object = try? JSONSerialization.jsonObject(with: data),
              let dictionary = object as? [String : String] else {
            self.textsByKey = [:]
            self.templates = []
            return
        }

        self.textsByKey = dictionary
        self.templates = ScriptTextTable.makeTemplates(from: dictionary)
    }

    public func localizedText(for text: String) -> String {
        if textsByKey.isEmpty || text.isEmpty {
            return text
        }

        lock.lock()
        let cached = cache[text]
        lock.unlock()
        if let cached {
            return cached
        }

        let result = translateBlock(text) ?? translateLines(text)

        lock.lock()
        cache[text] = result
        lock.unlock()

        return result
    }

    // MARK: - Private

    private func translateBlock(_ text: String) -> String? {
        if let translation = textsByKey[text] {
            return translation
        }
        if let translation = matchTemplate(text) {
            return translation
        }

        let trimmed = text.trimmingCharacters(in: .whitespacesAndNewlines)
        if !trimmed.isEmpty && trimmed != text {
            if let translation = textsByKey[trimmed] {
                return translation
            }
            if let translation = matchTemplate(trimmed) {
                return translation
            }
        }

        return nil
    }

    private func translateLines(_ text: String) -> String {
        guard text.contains("\n") else {
            return text
        }

        let lines = text.components(separatedBy: "\n").map { line in
            line.isEmpty ? line : (translateBlock(line) ?? line)
        }
        return lines.joined(separator: "\n")
    }

    private func matchTemplate(_ text: String) -> String? {
        let nsText = text as NSString
        let range = NSRange(location: 0, length: nsText.length)

        for template in templates where text.hasPrefix(template.prefix) {
            guard let match = template.regex.firstMatch(in: text, options: [], range: range) else {
                continue
            }

            var values: [Int : String] = [:]
            for (offset, index) in template.placeholderIndices.enumerated() where values[index] == nil {
                let groupRange = match.range(at: offset + 1)
                values[index] = groupRange.location == NSNotFound ? "" : nsText.substring(with: groupRange)
            }

            var result = template.translation
            for (index, value) in values {
                result = result.replacingOccurrences(of: "{\(index)}", with: value)
            }
            return result
        }

        return nil
    }

    private static func makeTemplates(from dictionary: [String : String]) -> [Template] {
        guard let placeholderRegex = try? NSRegularExpression(pattern: "\\{(\\d+)\\}") else {
            return []
        }

        var templates: [Template] = []

        for (key, translation) in dictionary where key.contains("{") {
            let nsKey = key as NSString
            let matches = placeholderRegex.matches(in: key, options: [], range: NSRange(location: 0, length: nsKey.length))
            if matches.isEmpty {
                continue
            }

            // Skip keys that are almost only placeholders; they would match everything.
            let literalText = placeholderRegex.stringByReplacingMatches(in: key, options: [], range: NSRange(location: 0, length: nsKey.length), withTemplate: "")
            if literalText.trimmingCharacters(in: .whitespacesAndNewlines).count < 3 {
                continue
            }

            var pattern = "^"
            var indices: [Int] = []
            var location = 0
            for match in matches {
                let literal = nsKey.substring(with: NSRange(location: location, length: match.range.location - location))
                pattern += NSRegularExpression.escapedPattern(for: literal)
                pattern += "(.*?)"
                indices.append(Int(nsKey.substring(with: match.range(at: 1))) ?? 0)
                location = match.range.location + match.range.length
            }
            pattern += NSRegularExpression.escapedPattern(for: nsKey.substring(from: location))
            pattern += "$"

            guard let regex = try? NSRegularExpression(pattern: pattern, options: []) else {
                continue
            }

            let prefix = nsKey.substring(to: matches[0].range.location)
            templates.append(Template(prefix: prefix, regex: regex, placeholderIndices: indices, translation: translation))
        }

        // More specific templates (longer literal prefix) win.
        templates.sort { $0.prefix.count > $1.prefix.count }
        return templates
    }
}
